section('Counts after the scope filters');
const count = (label, n) => console.log(`  ${label.padEnd(24)} ${n}`);
const fromOf = (k) => skills.filter((s) => s.from.includes(k)).length;
count('weapons / armor / misc', `${W.length} / ${A.length} / ${M.length} (${BASES.length} bases)`);
count('item types', Object.keys(X.D2X_ITEM_TYPES).length);
count('prefixes / suffixes', `${X.D2X_PREFIXES.length} / ${X.D2X_SUFFIXES.length}, automagic ${X.D2X_AUTOMAGIC.length}`);
