count('runewords', X.D2X_RUNEWORDS.length);
count('runes / gems', `${X.D2X_RUNES.length} / ${X.D2X_GEMS.length}`);
count('classes', Object.keys(X.D2X_CLASSES).join(' '));
count('Act 1 areas', X.D2X_AREAS.length);
count('monsters', `${Object.keys(X.D2X_MONSTERS).length} (${Object.values(X.D2X_MONSTERS).filter((m) => m.name).length} named)`);
count('superuniques', X.D2X_SUPERUNIQUES.length);
count('treasure classes', `${Object.keys(TCS).length} (${Object.values(TCS).filter((t) => t.auto).length} automatic)`);
count('skills', `${skills.length}: class ${fromOf('class')}, monster ${fromOf('monster')}, umod ${fromOf('umod')}, hireling ${fromOf('hireling')}, summon ${fromOf('summon')}, missile ${fromOf('missile')}`);
count('named-only skills', Object.keys(X.D2X_SKILL_REFS).length);
count('missiles / states', `${Object.keys(X.D2X_MISSILES).length} / ${Object.keys(X.D2X_STATES).length}`);
count('hirelings / names', `${X.D2X_HIRELINGS.length} / ${Object.keys(X.D2X_HIRELING_NAMES).length}`);
count('gamble bases', X.D2X_GAMBLE.length);

section('Files');
// (types.ts is written by hand)
check('every generated src/data/d2x file starts with the generated-file header', files.filter((f) => f !== 'types.ts' && !fs.readFileSync(path.join(D2X, f), 'utf8').startsWith(HEAD)));

// ───────────────────────── scope ─────────────────────────
section('Scope: before the Warlock expansion, nothing still ladder-only');
/** every property list in the data, with where it is */
const allProps = [
  ...[...X.D2X_PREFIXES, ...X.D2X_SUFFIXES, ...X.D2X_AUTOMAGIC].map((a) => [`affix ${a.id}`, a.props]),
  ...X.D2X_QUALITY.map((q) => [`superior ${q.id}`, q.props]),
  ...X.D2X_UNIQUES.map((u) => [`unique ${u.key}`, u.props]),
  ...X.D2X_SET_ITEMS.map((s) => [`set item ${s.key}`, [...s.props, ...(s.bonus ?? []).flat()]]),
  ...X.D2X_SETS.map((s) => [`set ${s.id}`, [...s.partial.flatMap((p) => p.props), ...s.full]]),
  ...X.D2X_RUNEWORDS.map((r) => [`runeword ${r.id}`, r.props]),
  ...[...X.D2X_RUNES, ...X.D2X_GEMS].map((g) => [`socketable ${g.id}`, [...g.weapon, ...g.armor, ...g.shield]]),
  ...Object.values(X.D2X_MONSTERS).filter((m) => m.props).map((m) => [`monster ${m.id}`, m.props.flat()]),
];
check('no Warlock class', Object.keys(X.D2X_CLASSES).filter((c) => c === WARLOCK));
check('no Warlock item type', Object.keys(X.D2X_ITEM_TYPES).filter((t) => WARLOCK_TYPES.has(t)));
check('no base of a Warlock item type', BASES.filter((b) => WARLOCK_TYPES.has(b.type) || WARLOCK_TYPES.has(b.type2)).map((b) => b.code));
const kindOf = (b) => (W.includes(b) ? 'weapons' : A.includes(b) ? 'armor' : 'misc');
check('no base the expansion added (all are in 2.7)', BASES.filter((b) => !rows(R27[kindOf(b)]).some((r) => r.code === b.code)).map((b) => b.code));
